SELECT p."assignment_id",p."__version_normalized",p."index1",p."punya_nib",p."mempunyai_laporan_keuangan",p."__key_valid",p."__conflict" FROM mart_legalitas_usaha p WHERE p.__key_valid=1 AND p.__conflict=0 AND EXISTS (SELECT 1 FROM mart_usaha u WHERE u.assignment_id=p.assignment_id AND u.__version_normalized=p.__version_normalized AND u.index1=p.index1 AND u.kode_keberadaan_usaha IN ('1','2')) AND EXISTS (SELECT 1 FROM mart_assignment_tgr a WHERE a.assignment_id=p.assignment_id AND a.status_assignment IN ('APPROVED BY Pengawas','COMPLETED BY Admin Kabupaten'))
